def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(s):
        if not s or any(c < "0" or c > "9" for c in s):
            return None
        value = 0
        for i in range(0, len(s), 9):
            chunk = s[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        if any(not part for part in parts):
            rejected.append(index)
            continue

        verb = parts[0]
        success = False

        if verb == "undo" and len(parts) == 1:
            if history:
                for account, old_balance, was_frozen in history.pop():
                    if old_balance is None:
                        del balances[account]
                        frozen.discard(account)
                    else:
                        balances[account] = old_balance
                        if was_frozen:
                            frozen.add(account)
                        else:
                            frozen.discard(account)
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])

            if amount is not None:
                if verb == "open":
                    if account not in balances:
                        history.append([(account, None, False)])
                        balances[account] = amount
                        success = True
                elif amount > 0 and account in balances:
                    if verb == "deposit":
                        history.append(
                            [(account, balances[account], account in frozen)]
                        )
                        balances[account] += amount
                        success = True
                    elif account not in frozen and balances[account] >= amount:
                        history.append([(account, balances[account], False)])
                        balances[account] -= amount
                        success = True

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])

            if (
                amount is not None
                and amount > 0
                and source != destination
                and source in balances
                and destination in balances
                and source not in frozen
                and balances[source] >= amount
            ):
                history.append([
                    (source, balances[source], False),
                    (destination, balances[destination], destination in frozen),
                ])
                balances[source] -= amount
                balances[destination] += amount
                success = True

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if account in balances:
                was_frozen = account in frozen
                if verb == "freeze" and not was_frozen:
                    history.append([(account, balances[account], False)])
                    frozen.add(account)
                    success = True
                elif verb == "unfreeze" and was_frozen:
                    history.append([(account, balances[account], True)])
                    frozen.remove(account)
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
